changeSet.sql:
-- 1. Cour Constitutionnelle (CCR) (fonction 738 - RO-d) INSERT INTO parser (name, description, dataset_name, list_type, website_url, plugin_id, plugin_url, data_source_type, parser_kind, source_location, parameters, refresh_hours, retention_months, licence, attribution, notes, enabled, created_at) VALUES ('PEP Roumanie – Cour Constitutionnelle (CCR)', 'Juges de la Cour Constitutionnelle de Roumanie (Curtea Constituțională a României) (catégorie RO-d)', 'ro_pep_constitutional_court', 'PEP', 'https://www.ccr.ro/', 'ro-pep-constitutional-court', 'D:/test parser 2/plugins/swiftcheck-aml-ro-pep-constitutional-court-0.0.1-SNAPSHOT.jar', 'PLUGIN_MANAGED', 'API', NULL, '{"url": "https://www.ccr.ro/judecatori/"}', 168, 12, 'Données publiques ouvertes : citer la source', 'Curtea Constituțională a României', 'Les 9 juges constitutionnels de Roumanie dont le président.', TRUE, NOW());
INSERT INTO pep_function_parser (function_id, parser_id, completeness, includes_former, covered_scope, gaps) SELECT f.id, p.id, 'COMPLETE', TRUE, 'Juges de la Cour Constitutionnelle de Roumanie (CCR)', NULL FROM pep_function f JOIN pep_category c ON c.id = f.category_id, parser p WHERE c.country_iso = 'RO' AND f.id = 738 AND p.dataset_name = 'ro_pep_constitutional_court';
